<script setup>
import PublicLayout from '../../../Layouts/PublicLayout.vue';import {useForm} from '@inertiajs/vue3';import {ArrowLeft,Save} from 'lucide-vue-next';
import AdminQuickLinks from '../../../Components/AdminQuickLinks.vue';
const props=defineProps({archive:Object,categories:Array});const form=useForm({title:props.archive?.title||'',category:props.archive?.category||'Heritage',subtitle:props.archive?.subtitle||'',summary:props.archive?.summary||'',body:props.archive?.body||'',record_year:props.archive?.record_year||'',source_title:props.archive?.source_title||'',source_page:props.archive?.source_page||'',cover_image:null,attachment:null,is_featured:!!props.archive?.is_featured,is_published:!!props.archive?.is_published});const submit=()=>props.archive?form.post(`/admin/archives/${props.archive.id}?_method=PUT`,{forceFormData:true}):form.post('/admin/archives',{forceFormData:true});
</script>
<template><PublicLayout><section class="bg-[#00351F] text-white"><div class="mx-auto max-w-4xl px-5 py-10"><a href="/admin/archives" class="text-sm text-white/70"><ArrowLeft class="mr-1 inline" :size="15"/> Back to archive records</a><h1 class="mt-4 text-3xl font-extrabold">{{archive?'Edit Archive Record':'Create Archive Record'}}</h1><p class="mt-2 text-sm text-white/70">Keep the original source and page reference wherever possible.</p></div><AdminQuickLinks />
    </section><section class="bg-[#F7F9F7] py-10"><form @submit.prevent="submit" class="mx-auto max-w-4xl space-y-5 rounded-2xl border bg-white p-6"><div class="grid gap-5 sm:grid-cols-2"><label class="text-sm font-semibold">Title<input v-model="form.title" required class="mt-1 w-full rounded-lg border-gray-300"/><small v-if="form.errors.title" class="text-red-600">{{form.errors.title}}</small></label><label class="text-sm font-semibold">Category<select v-model="form.category" class="mt-1 w-full rounded-lg border-gray-300"><option v-for="c in categories" :key="c">{{c}}</option></select></label><label class="text-sm font-semibold">Subtitle<input v-model="form.subtitle" class="mt-1 w-full rounded-lg border-gray-300"/></label><label class="text-sm font-semibold">Historical year<input v-model="form.record_year" type="number" min="1900" max="2100" class="mt-1 w-full rounded-lg border-gray-300"/></label><label class="text-sm font-semibold">Source / Publication<input v-model="form.source_title" placeholder="e.g. 2025 Founders’ Day brochure" class="mt-1 w-full rounded-lg border-gray-300"/></label><label class="text-sm font-semibold">Source page(s)<input v-model="form.source_page" placeholder="e.g. 8 or 66–77" class="mt-1 w-full rounded-lg border-gray-300"/></label></div><label class="block text-sm font-semibold">Summary<textarea v-model="form.summary" rows="3" class="mt-1 w-full rounded-lg border-gray-300"/></label><label class="block text-sm font-semibold">Full content / historical details<textarea v-model="form.body" rows="10" class="mt-1 w-full rounded-lg border-gray-300"/></label><div class="grid gap-5 sm:grid-cols-2"><label class="block text-sm font-semibold">Cover image<input type="file" accept="image/*" @input="form.cover_image=$event.target.files[0]" class="mt-2 block w-full text-sm"/></label><label class="block text-sm font-semibold">Source attachment (PDF / document)<input type="file" accept=".pdf,.doc,.docx,image/*" @input="form.attachment=$event.target.files[0]" class="mt-2 block w-full text-sm"/></label></div><div class="flex flex-wrap gap-6"><label class="flex items-center gap-2 text-sm"><input v-model="form.is_featured" type="checkbox" class="rounded"/> Feature this record</label><label class="flex items-center gap-2 text-sm"><input v-model="form.is_published" type="checkbox" class="rounded"/> Publish publicly</label></div><p class="rounded-lg bg-amber-50 p-3 text-xs text-amber-800">Please verify historical names, dates and titles with the Association before publishing. Draft records remain private.</p><div class="flex justify-end"><button :disabled="form.processing" class="rounded-lg bg-[#006B3C] px-6 py-3 font-bold text-white"><Save class="mr-2 inline" :size="17"/>{{form.processing?'Saving...':'Save Archive Record'}}</button></div></form></section></PublicLayout></template>
